import cookieSession from 'cookie-session';
import Keygrip from 'keygrip';

app.use(cookieSession({
  name: 'session',
  keys: new Keygrip([process.env.SESSION_KEY, process.env.SESSION_KEY_OLD], 'SHA384', 'base64'),
  httpOnly: true, secure: true, sameSite: 'lax', maxAge: 30 * 60 * 1000,
}));

app.post('/cart', (req, res) => {
  req.session.items = [...(req.session.items ?? []), req.body.sku];  // signed into the cookie
  res.sendStatus(204);
});
